/**
 * ZVYRA shared integration contract — domain types.
 *
 * Ownership: SHARED. Changes require a CONTRACT_VERSION bump and an entry in
 * docs/CONTRACT.md ("Changelog"). The UI (renderer) and the backend (Astra)
 * both compile against these types. Keep everything JSON-serialisable:
 * values cross Electron IPC via structured clone.
 *
 * Conventions
 *  - Timestamps are ISO-8601 strings (UTC).
 *  - IDs are opaque strings generated by the backend.
 *  - Optional fields are omitted (not null) unless null carries meaning.
 */

export type ISODate = string

/* ------------------------------------------------------------------ */
/* System                                                              */
/* ------------------------------------------------------------------ */

export interface SystemInfo {
  contractVersion: string
  /** 'mock' is reserved for the UI preview adapter. Real backends must not use it. */
  backend: string
  backendVersion: string
  appVersion: string
  platform: string
  dataPath?: string
  /** Feature flags the backend actually implements. UI hides or marks unsupported surfaces. */
  capabilities: Partial<Record<Capability, boolean>>
}

export type Capability =
  | 'voice'
  | 'wakeWord'
  | 'chat'
  | 'chatStreaming'
  | 'chatAttachments'
  | 'tasks'
  | 'taskPause'
  | 'agents'
  | 'computerControl'
  | 'terminal'
  | 'files'
  | 'browser'
  | 'codeEditor'
  | 'projects'
  | 'memory'
  | 'automations'
  | 'notifications'
  | 'calls'
  | 'apps'
  | 'diagnostics'
  /** (1.2.0) Engine honours voice sensitivity, timeouts, rate and device settings. */
  | 'voiceTuning'

export type LogLevel = 'debug' | 'info' | 'warn' | 'error'

export interface LogEntry {
  ts: ISODate
  level: LogLevel
  scope: string
  message: string
  /** Must already be redacted by the backend (no secrets, no raw audio). */
  data?: Record<string, unknown>
}

export interface DiagnosticCheck {
  id: string
  label: string
  status: 'ok' | 'warning' | 'error' | 'unknown'
  detail?: string
  /** Optional settings route the UI can deep-link to, e.g. "settings/swarm". */
  fixRoute?: string
}

/* ------------------------------------------------------------------ */
/* Voice                                                               */
/* ------------------------------------------------------------------ */

export type VoiceState =
  | 'off' // listening disabled, no capture running
  | 'standby' // wake-word detector running, waiting for "Hey Zvyra"
  | 'wake_detected' // short transitional state after detection
  | 'listening' // capturing the user's command
  | 'transcribing' // converting captured audio to text
  | 'speaking' // TTS playback in progress
  | 'error'
  | 'unavailable' // required engine/microphone missing — see setupRequired

export type ProcessingLocation = 'local' | 'external'

export interface VoiceEngineStatus {
  id: string
  name: string
  ready: boolean
  processing: ProcessingLocation
  /** Human-readable reason the engine cannot run yet (missing model, key, device…). */
  setupRequired?: string
}

export interface VoiceStatus {
  state: VoiceState
  wakeWordEnabled: boolean
  wakePhrase: string
  wake: VoiceEngineStatus
  stt: VoiceEngineStatus
  tts: VoiceEngineStatus
  micAvailable: boolean
  micDeviceId: string | null
  /** (1.3.0) Name of the microphone currently capturing, if any. */
  micLabel?: string
  /** Text recognised so far in the current capture, if the engine supports partials. */
  partialTranscript?: string
  lastTranscript?: string
  error?: string
  /**
   * (1.4.0) True while on-device voice activity detection hears the user
   * speaking during a conversation (drives the "speech detected" indicator).
   */
  userSpeaking?: boolean
}

export interface MicDevice {
  id: string
  label: string
  isDefault: boolean
}

export interface VoiceEngineOption {
  id: string
  kind: 'wake' | 'stt' | 'tts'
  name: string
  processing: ProcessingLocation
  description: string
  installed: boolean
  /** Fields the settings UI renders for configuration. Secret fields are write-only. */
  fields: ConfigField[]
}

export interface ConfigField {
  key: string
  label: string
  type: 'text' | 'secret' | 'number' | 'select' | 'file' | 'boolean'
  required?: boolean
  placeholder?: string
  help?: string
  options?: { value: string; label: string }[]
  /** Current value for non-secret fields; secrets report only `hasValue`. */
  value?: string | number | boolean
  hasValue?: boolean
}

/* ------------------------------------------------------------------ */
/* Assistant interactions (island / home / voice entry point)          */
/* ------------------------------------------------------------------ */

export type InteractionSource = 'voice' | 'island' | 'home' | 'chat' | 'automation' | 'api'

export interface Interaction {
  id: string
  source: InteractionSource
  input: string
  status: 'pending' | 'streaming' | 'done' | 'error' | 'cancelled'
  /** Assistant reply text so far (grows while streaming). */
  response?: string
  /** Set when the backend turned the request into a task. */
  taskId?: string
  conversationId?: string
  error?: string
  createdAt: ISODate
  updatedAt: ISODate
}

/* ------------------------------------------------------------------ */
/* Tasks                                                               */
/* ------------------------------------------------------------------ */

export type TaskStatus =
  | 'queued'
  | 'planning'
  | 'running'
  | 'paused'
  | 'waiting_permission'
  | 'verifying'
  | 'completed'
  | 'failed'
  | 'cancelled'
  | 'interrupted' // app shut down while the task was active

export const ACTIVE_TASK_STATUSES: readonly TaskStatus[] = [
  'queued',
  'planning',
  'running',
  'paused',
  'waiting_permission',
  'verifying'
]

export interface TaskStep {
  id: string
  title: string
  status: 'pending' | 'running' | 'done' | 'failed' | 'skipped'
}

export type TaskEventKind =
  | 'status'
  | 'plan'
  | 'thought'
  | 'tool_call'
  | 'tool_result'
  | 'output'
  | 'permission'
  | 'message'
  | 'verification'
  | 'error'

export interface TaskEvent {
  id: string
  taskId: string
  ts: ISODate
  kind: TaskEventKind
  message: string
  data?: Record<string, unknown>
}

export interface Task {
  id: string
  title: string
  instruction: string
  status: TaskStatus
  source: InteractionSource
  agentId?: string
  projectId?: string
  conversationId?: string
  model?: string
  createdAt: ISODate
  updatedAt: ISODate
  startedAt?: ISODate
  finishedAt?: ISODate
  plan: TaskStep[]
  currentAction?: string
  /**
   * Real progress only. Backends must leave this undefined when they cannot
   * count completed vs total units of work. The UI never invents percentages.
   */
  progress?: { completed: number; total: number }
  summary?: string
  output?: string
  error?: string
  canPause: boolean
  canResume: boolean
  canRetry: boolean
  automationId?: string
}

export interface CreateTaskInput {
  instruction: string
  source: InteractionSource
  agentId?: string
  projectId?: string
  model?: string
}

/* ------------------------------------------------------------------ */
/* Permissions                                                         */
/* ------------------------------------------------------------------ */

export type PermissionCategory =
  | 'read_files'
  | 'write_files'
  | 'delete_files'
  | 'run_commands'
  | 'open_apps'
  | 'browser'
  | 'network'
  | 'computer_input'
  | 'screen_capture'
  | 'memory_write'
  | 'external_communication'
  | 'system_settings'

export type PermissionPolicy = 'allow' | 'ask' | 'deny'

export type RiskLevel = 'low' | 'medium' | 'high'

export interface PermissionRequest {
  id: string
  taskId?: string
  agentId?: string
  category: PermissionCategory
  title: string
  description: string
  risk: RiskLevel
  details?: { label: string; value: string }[]
  createdAt: ISODate
  expiresAt?: ISODate
  /** (1.4.0) Exact command awaiting approval (desktop command approvals only). */
  command?: { shell: CommandShell; text: string; cwd: string }
  /** (1.4.0) Why approval is required, in one sentence. */
  reason?: string
  /** (1.4.0) Files or folders the action targets, when known. */
  targets?: string[]
  /** (1.4.0) Whether "Always allow" may be offered (never for high-risk actions). */
  canAlwaysAllow?: boolean
}

/** (1.4.0) `allow_always` saves a narrowly scoped rule (see CommandRule). */
export type PermissionDecision = 'allow_once' | 'allow_task' | 'allow_always' | 'deny'

export type CommandShell = 'powershell' | 'cmd'

/**
 * (1.4.0) A saved "Always allow" rule. It matches only the same shell, the same
 * program, the same normalised command text and the same working folder, and
 * only while the command still classifies at or below `risk`.
 */
export interface CommandRule {
  id: string
  shell: CommandShell
  program: string
  command: string
  cwd: string
  risk: RiskLevel
  createdAt: ISODate
  lastUsedAt?: ISODate
  uses: number
}

/** (1.4.0) Right-side desktop notification raised for a real ZVYRA event. */
export interface DesktopToast {
  id: string
  /** Events with the same key inside a short window are shown once. */
  key: string
  kind: 'approval' | 'approved' | 'denied' | 'success' | 'error' | 'file' | 'launch' | 'info'
  title: string
  body?: string
  /** Short technical detail (file path, command, exit code). */
  detail?: string
  ts: ISODate
  /** 0 = stays until dismissed or replaced. */
  timeoutMs: number
  /** Permission request this toast belongs to, so it can be cleared when answered. */
  permissionId?: string
}

export interface PermissionPolicyEntry {
  category: PermissionCategory
  policy: PermissionPolicy
  /** Backends may lock categories (e.g. delete_files can never be 'allow'). */
  allowedPolicies: PermissionPolicy[]
}

/* ------------------------------------------------------------------ */
/* Chat                                                                */
/* ------------------------------------------------------------------ */

export interface Conversation {
  id: string
  title: string
  createdAt: ISODate
  updatedAt: ISODate
  model?: string
  projectId?: string
  messageCount: number
  preview?: string
}

export interface Attachment {
  id: string
  name: string
  kind: 'text' | 'image' | 'file'
  size: number
}

export interface ChatMessage {
  id: string
  conversationId: string
  role: 'user' | 'assistant' | 'system'
  content: string
  createdAt: ISODate
  model?: string
  status: 'complete' | 'streaming' | 'error' | 'stopped'
  error?: string
  attachments?: Attachment[]
  taskId?: string
}

/* ------------------------------------------------------------------ */
/* SWARM + model routing                                               */
/* ------------------------------------------------------------------ */

export type ConnectionStatus = 'disconnected' | 'connecting' | 'connected' | 'error'

export interface SwarmConnection {
  status: ConnectionStatus
  baseUrl: string
  hasApiKey: boolean
  lastCheckedAt?: ISODate
  latencyMs?: number
  error?: string
  /** Free-form account details the backend reports (e.g. credit balance, provider health). */
  account?: { label: string; value: string }[]
  /**
   * (1.1.0) Endpoint values the backend accepts for `swarm.configure`, rendered as
   * a picker in Settings → SWARM. Omit to show a free-text endpoint field only.
   */
  endpointPresets?: { value: string; label: string; configured?: boolean }[]
}

export interface ModelInfo {
  id: string
  ownedBy?: string
  available: boolean
  supportsVision?: boolean
  contextWindow?: number
  pricing?: { inputPerMillion?: number; outputPerMillion?: number; currency?: string }
}

export type RoutingRole = 'conversation' | 'coding' | 'research' | 'computer' | 'general' | 'voice'

export interface RoutingConfig {
  mode: 'auto' | 'manual'
  /** Model id per role; null = use backend's automatic choice for that role. */
  roles: Record<RoutingRole, string | null>
  fallbacks: string[]
  timeoutMs: number
  maxRetries: number
}

/* ------------------------------------------------------------------ */
/* Agents                                                              */
/* ------------------------------------------------------------------ */

export interface AgentInfo {
  id: string
  name: string
  role: RoutingRole | string
  description: string
  tools: string[]
  enabled: boolean
  state: 'idle' | 'running' | 'waiting' | 'error' | 'disabled'
  activeTaskIds: string[]
  model?: string
  lastError?: string
}

export interface AgentRuntime {
  /** Honest description of execution: one queue vs truly concurrent workers. */
  mode: 'sequential' | 'parallel'
  maxConcurrentTasks: number
  runningTasks: number
  queuedTasks: number
}

