/* ------------------------------------------------------------------ */
/* Live tool activity (shown as animated cards in the Dynamic Island)  */
/* ------------------------------------------------------------------ */

export type ToolKind = 'research' | 'media' | 'camera' | 'build' | 'weather' | 'system' | 'timer' | 'web' | 'other'

export interface ToolSource {
  title: string
  url: string
}

export interface ToolActivity {
  id: string
  /** Tool name as declared to the model, e.g. web_search. */
  tool: string
  kind: ToolKind
  /** Short headline, e.g. “Researching”, “Playing on YouTube”. */
  label: string
  status: 'running' | 'done' | 'error'
  /** What the tool is working on (query, song, project name…). */
  subject?: string
  /** Result text (trimmed) or error message. */
  summary?: string
  sources?: ToolSource[]
  /** Recent progress steps for long-running tools (builder agent). */
  steps?: string[]
  startedAt: ISODate
  updatedAt: ISODate
}

